import React, { useState, useEffect } from 'react';
import * as inventoryApi from '../api/inventory';
import './Inventory.css';

interface LowStockItem {
  product_id: number;
  product_name: string;
  quantity: number;
  reserved: number;
  available: number;
  low_stock_threshold: number;
}

const Inventory: React.FC = () => {
  const [lowStock, setLowStock] = useState<LowStockItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadLowStock();
  }, []);

  const loadLowStock = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await inventoryApi.getLowStock();
      setLowStock(data);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load inventory data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading inventory...</div>;
  }

  return (
    <div className="inventory-page">
      <h1>Inventory Management</h1>

      {error && <div className="error-message">{error}</div>}

      <div className="inventory-section">
        <h2>Low Stock Alerts</h2>
        {lowStock.length === 0 ? (
          <div className="no-alerts">No low stock items</div>
        ) : (
          <div className="inventory-table">
            <table>
              <thead>
                <tr>
                  <th>Product</th>
                  <th>Total Quantity</th>
                  <th>Reserved</th>
                  <th>Available</th>
                  <th>Threshold</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {lowStock.map(item => (
                  <tr key={item.product_id}>
                    <td>{item.product_name}</td>
                    <td>{item.quantity}</td>
                    <td>{item.reserved}</td>
                    <td>{item.available}</td>
                    <td>{item.low_stock_threshold}</td>
                    <td>
                      <span className="status-badge low-stock">Low Stock</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;
