import axios from './axios';
import { Product, Category, Recommendation } from '../types';

export const getProducts = async (params?: any) => {
  const response = await axios.get('/products', { params });
  return response.data;
};

export const getProduct = async (id: number): Promise<Product> => {
  const response = await axios.get(`/products/${id}`);
  return response.data;
};

export const getCategories = async (): Promise<Category[]> => {
  const response = await axios.get('/categories');
  return response.data.categories;
};

export const getRecommendations = async (): Promise<Recommendation[]> => {
  try {
    const response = await axios.get('/recommendations');
    return response.data.recommendations;
  } catch (error) {
    return [];
  }
};

export const getSimilarProducts = async (productId: number): Promise<Recommendation[]> => {
  try {
    const response = await axios.get(`/recommendations/similar/${productId}`);
    return response.data.similar_products;
  } catch (error) {
    return [];
  }
};
