import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import ProductCard from '../components/ProductCard';
import { useCart } from '../contexts/CartContext';
import { Product, Recommendation } from '../types';
import * as api from '../api/products';
import './ProductDetail.css';

const ProductDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { addToCart } = useCart();

  const [product, setProduct] = useState<Product | null>(null);
  const [similarProducts, setSimilarProducts] = useState<Recommendation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [addedToCart, setAddedToCart] = useState(false);

  useEffect(() => {
    if (id) {
      loadProduct(parseInt(id));
      loadSimilarProducts(parseInt(id));
    }
  }, [id]);

  const loadProduct = async (productId: number) => {
    setLoading(true);
    setError('');

    try {
      const data = await api.getProduct(productId);
      setProduct(data);
    } catch (err: any) {
      setError('Product not found');
    } finally {
      setLoading(false);
    }
  };

  const loadSimilarProducts = async (productId: number) => {
    try {
      const data = await api.getSimilarProducts(productId);
      setSimilarProducts(data);
    } catch (err) {
      console.error('Failed to load similar products');
    }
  };

  const handleAddToCart = () => {
    if (product) {
      addToCart(product, quantity);
      setAddedToCart(true);
      setTimeout(() => setAddedToCart(false), 2000);
    }
  };

  if (loading) {
    return <div className="loading">Loading product...</div>;
  }

  if (error || !product) {
    return (
      <div className="container">
        <div className="error-message">{error || 'Product not found'}</div>
        <button onClick={() => navigate('/')} className="button button-primary">
          Back to Shop
        </button>
      </div>
    );
  }

  return (
    <>
      <Helmet>
        <title>{product.name} - Product Catalog</title>
        <meta name="description" content={product.description} />
      </Helmet>

      <div className="container">
        <button onClick={() => navigate('/')} className="back-button">
          ← Back to Products
        </button>

        <div className="product-detail">
          <div className="product-image-large">
            {product.image_url ? (
              <img src={product.image_url} alt={product.name} />
            ) : (
              <div className="no-image-large">No Image Available</div>
            )}
          </div>

          <div className="product-details">
            <h1>{product.name}</h1>

            <div className="product-rating">
              <span className="stars">{'★'.repeat(Math.round(product.rating))}</span>
              <span className="rating-text">
                {product.rating.toFixed(1)} ({product.review_count} reviews)
              </span>
            </div>

            <div className="product-price-large">
              ${product.price.toFixed(2)}
            </div>

            {product.in_stock ? (
              <div className="stock-status in-stock">✓ In Stock</div>
            ) : (
              <div className="stock-status out-of-stock">Out of Stock</div>
            )}

            <p className="product-description">{product.description}</p>

            {product.in_stock && (
              <div className="purchase-section">
                <div className="quantity-selector">
                  <label>Quantity:</label>
                  <div className="quantity-controls">
                    <button
                      onClick={() => setQuantity(Math.max(1, quantity - 1))}
                      className="quantity-button"
                    >
                      -
                    </button>
                    <input
                      type="number"
                      value={quantity}
                      onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                      min="1"
                      className="quantity-input"
                    />
                    <button
                      onClick={() => setQuantity(quantity + 1)}
                      className="quantity-button"
                    >
                      +
                    </button>
                  </div>
                </div>

                <button onClick={handleAddToCart} className="button button-primary add-to-cart-button">
                  {addedToCart ? '✓ Added to Cart' : 'Add to Cart'}
                </button>
              </div>
            )}
          </div>
        </div>

        {similarProducts.length > 0 && (
          <section className="similar-products">
            <h2>Similar Products</h2>
            <div className="similar-products-grid">
              {similarProducts.map(similar => (
                <ProductCard key={similar.id} product={similar as Product} />
              ))}
            </div>
          </section>
        )}
      </div>
    </>
  );
};

export default ProductDetail;
```

